       "dir": "ltr",
       "code": "public static void Bubble_Sort(int[] A)\n{\n    for (int i = A.Length - 1; i >= 0; i--)\n    {\n        for (int j = 1; j <= i; j++)\n        {\n            if (A[j - 1] > A[j])\n            {\n                int Temp = A[j - 1];\n                A[j - 1] = A[j];\n                A[j] = Temp;\n            }\n        }\n    }\n}",
       "origin": "book"
